//! The PIC32CK1025 and PIC32CK2051, SG01 and GC01 (one die: the GC without
//! `TrustZone` and the HSM, the 1025 with half the flash), in each of
//! their packages: their interrupts (from the SG PAC's `Interrupt`, in
//! vector order), the peripheral singletons the drivers take so far, and
//! the package's pins.
//!
//! What a package has is in its pins file, `pic32ck_pins_064.rs`, `_100.rs`
//! or `_144.rs`: its GPIO pins and the pin tables cut to them. Those are
//! generated by `tools/pin_tables.py --pins-file` from the devices' pin
//! multiplexing; the rest of the chip is here, by hand. The registers are
//! the same in every package (the PACs are the 144-pin devices'), except
//! that the 64-pin package has no high-speed USB.
//!
//! The pin multiplexing is Microchip's device packs', corrected where the
//! datasheet (DS60001795) or the silicon says otherwise. Two corrections
//! show in the pins files. PA02 and PA03 carry only SWD: the packs also
//! give them SERCOM6 pads and EIC lines, which the datasheet does not. And
//! the full-speed USB's D- and D+ are port pads PD03 and PD04 in every
//! package, as the packs' signals have them and as `usb` needs (it selects
//! function H on them); the 144-pin pinout names the pins `USB_DM` and
//! `USB_DP`, and the datasheet gives them no port name.
//!
//! Only the 144-pin PIC32CK2051 has run on a board. The other devices
//! build, on the same registers and the pins their packages have.

#[cfg(pic32ck_gc)]
pub use pic32ck_gc01_pac as pac;
#[cfg(pic32ck_sg)]
pub use pic32ck_sg01_pac as pac;

/// Program flash: two panels of 1 MiB on the PIC32CK2051, of 512 KiB on the
/// PIC32CK1025.
#[cfg(pic32ck_2051)]
pub const FLASH_SIZE: usize = 2 << 20;
#[cfg(pic32ck_1025)]
pub const FLASH_SIZE: usize = 1 << 20;

/// PORT as Secure code reaches it: the Secure view on the SG, the only
/// view on the GC.
#[cfg(pic32ck_sg)]
pub(crate) const PORT: usize = 0x4480_1000;
#[cfg(pic32ck_gc)]
pub(crate) const PORT: usize = 0x4480_0000;

/// The EIC as Secure code reaches it, likewise.
#[cfg(all(pic32ck_sg, feature = "exti"))]
pub(crate) const EIC: usize = 0x4401_B000;
#[cfg(all(pic32ck_gc, feature = "exti"))]
pub(crate) const EIC: usize = 0x4401_A000;

